// dist/actions/utility.js
var DEVICE_TYPE_LABELS = {
  uap: "Access Point",
  usw: "Switch",
  ugw: "Gateway",
  usg: "Gateway",
  udm: "Dream Machine",
  uxg: "UXG Gateway",
  usp: "UPS"
};
var COMMAND_SPEC = {
  "block-sta": { endpoint: "cmd/stamgr", macField: "mac" },
  "unblock-sta": { endpoint: "cmd/stamgr", macField: "mac" },
  "kick-sta": { endpoint: "cmd/stamgr", macField: "mac" },
  "forget-sta": { endpoint: "cmd/stamgr", macField: "macs" },
  "authorize-guest": { endpoint: "cmd/stamgr", macField: "mac" },
  "unauthorize-guest": { endpoint: "cmd/stamgr", macField: "mac" },
  adopt: { endpoint: "cmd/devmgr", macField: "macs" },
  restart: { endpoint: "cmd/devmgr", macField: "macs" },
  "power-cycle": { endpoint: "cmd/devmgr", macField: "mac" },
  "force-provision": { endpoint: "cmd/devmgr", macField: "macs" },
  "delete-device": { endpoint: "cmd/sitemgr", macField: "mac" },
  "set-locate": { endpoint: "cmd/devmgr", macField: "mac" },
  "unset-locate": { endpoint: "cmd/devmgr", macField: "mac" }
};
var DEVICE_COMMAND_REQUIRES_TYPE = {
  "power-cycle": "usw"
};
function buildUtilityActions(self2) {
  return {
    // Send Device Command: pick a client or device from a live-updating list pulled from the console
    // (self.devices/self.clients, refreshed every 60s by ModuleInstance.refreshInventory), then what
    // to do to it — this action builds the correct UniFi API request internally, so no MAC/path/
    // payload typing is required. Backed by unifi-api-ts: unifi.customApiRequest(...), with the exact
    // endpoint/payload shape per command verified against unifi-api-ts's own source (see COMMAND_SPEC).
    utility_send_device_command: {
      name: "Utility: Send Device Command",
      description: "Runs a command against a client device (phone, laptop, etc) or a UniFi infrastructure device (AP, switch, gateway) \u2014 pick which kind below, then pick the specific one from the list and what to do to it. The list is pulled live from the console and refreshes automatically; if something you're looking for isn't in it yet, you can still type its MAC address directly. Some commands need one extra field, which only appears once that command is selected.",
      options: [
        {
          id: "target_type",
          type: "dropdown",
          label: "Target Type",
          tooltip: "Whether to target a client device (phone, laptop, etc) or a piece of UniFi infrastructure (AP, switch, gateway).",
          choices: [
            { id: "client", label: "Client Device (phone, laptop, etc)" },
            { id: "device", label: "Infrastructure Device (AP, switch, gateway)" }
          ],
          default: "client",
          disableAutoExpression: true
        },
        {
          id: "client_mac",
          type: "dropdown",
          label: "Client",
          tooltip: "Pick a client from the list (pulled live from the console) \u2014 or type a MAC address directly, e.g. aa:bb:cc:dd:ee:ff, if it isn't in the list yet.",
          choices: self2.clients.map((c) => ({
            id: c.mac,
            label: `${c.name ?? c.hostname ?? c.mac} \u2014 ${c.mac}`
          })),
          default: "",
          allowCustom: true,
          isVisibleExpression: '$(options:target_type) == "client"'
        },
        {
          id: "client_command",
          type: "dropdown",
          label: "Client Command",
          tooltip: "What to do to the client selected above.",
          choices: [
            { id: "block-sta", label: "Block Client" },
            { id: "unblock-sta", label: "Unblock Client" },
            { id: "kick-sta", label: "Reconnect Client (kick and rejoin)" },
            { id: "forget-sta", label: "Forget Client (remove from known clients)" },
            { id: "authorize-guest", label: "Authorize Guest (needs Guest Minutes below)" },
            { id: "unauthorize-guest", label: "Unauthorize Guest" }
          ],
          default: "kick-sta",
          disableAutoExpression: true,
          isVisibleExpression: '$(options:target_type) == "client"'
        },
        {
          id: "device_mac",
          type: "dropdown",
          label: "Device",
          tooltip: "Pick a device from the list (pulled live from the console) \u2014 or type a MAC address directly, e.g. aa:bb:cc:dd:ee:ff, if it isn't in the list yet.",
          choices: self2.devices.map((d) => ({
            id: d.mac,
            label: `${d.name ?? d.model} (${DEVICE_TYPE_LABELS[d.type] ?? d.type}) \u2014 ${d.mac}`
          })),
          default: "",
          allowCustom: true,
          isVisibleExpression: '$(options:target_type) == "device"'
        },
        {
          id: "device_command",
          type: "dropdown",
          label: "Device Command",
          tooltip: `What to do to the device selected above. "Power Cycle Switch Port" only works on switches, and "Set Outlet Power" only works on a UniFi SmartPower device (UPS, UPS Pro, PDU Pro, Smart Plug, Smart Strip, etc) \u2014 picking either for a device that doesn't support it is rejected before anything is sent.`,
          choices: [
            { id: "restart", label: "Restart Device (needs Reboot Type below)" },
            { id: "power-cycle", label: "Power Cycle Switch Port (needs Switch Port below; switches only)" },
            { id: "force-provision", label: "Force Provision Device" },
            { id: "set-locate", label: "Locate Device (start blinking LED)" },
            { id: "unset-locate", label: "Locate Device (stop blinking LED)" },
            {
              id: "set-outlet",
              label: "Set Outlet Power (needs Outlet Number/Outlet On below; SmartPower devices only)"
            }
          ],
          default: "restart",
          disableAutoExpression: true,
          isVisibleExpression: '$(options:target_type) == "device"'
        },
        {
          id: "port_idx",
          type: "number",
          label: "Switch Port",
          tooltip: "The port number as labeled on the switch or shown in the UniFi app, e.g. 8.",
          default: 1,
          min: 1,
          max: 999999999,
          isVisibleExpression: '$(options:device_command) == "power-cycle"'
        },
        {
          id: "reboot_type",
          type: "dropdown",
          label: "Reboot Type",
          tooltip: "'soft' is a normal graceful reboot; 'hard' forces a rougher reboot for a device that's unresponsive.",
          choices: [
            { id: "soft", label: "soft (normal reboot)" },
            { id: "hard", label: "hard (force, for unresponsive devices)" }
          ],
          default: "soft",
          isVisibleExpression: '$(options:device_command) == "restart"'
        },
        {
          id: "minutes",
          type: "number",
          label: "Guest Minutes",
          tooltip: "How long the guest should have access, in minutes, e.g. 60 for one hour.",
          default: 60,
          min: 1,
          max: 999999999,
          isVisibleExpression: '$(options:client_command) == "authorize-guest"'
        },
        {
          id: "outlet_idx",
          type: "number",
          label: "Outlet Number",
          tooltip: "Which outlet on the device to control. Numbering isn't confirmed for every SmartPower model \u2014 start with 1, then check the physical outlet (or the UniFi app) to see which one actually switched, and adjust if it wasn't the one you expected. Not every outlet on every model can be switched independently \u2014 some are metering-only.",
          default: 1,
          min: 0,
          max: 999999999,
          isVisibleExpression: '$(options:device_command) == "set-outlet"'
        },
        {
          id: "outlet_on",
          type: "checkbox",
          label: "Outlet On",
          tooltip: "Set to true to power the outlet on, or false to power it off.",
          default: true,
          isVisibleExpression: '$(options:device_command) == "set-outlet"'
        }
      ],
      callback: async (event) => {
        const unifi = self2.unifi;
        if (!unifi) {
          self2.log("warn", "Utility: Send Device Command - not connected");
          return;
        }
        try {
          const targetType = event.options.target_type;
          const mac = (targetType === "client" ? event.options.client_mac : event.options.device_mac).trim().toLowerCase();
          if (!mac) {
            throw new Error(`${targetType === "client" ? "Client" : "Device"} is required`);
          }
          const command = targetType === "client" ? event.options.client_command : event.options.device_command;
          if (targetType === "device") {
            const requiredType = DEVICE_COMMAND_REQUIRES_TYPE[command];
            const device = self2.devices.find((d) => d.mac.toLowerCase() === mac);
            if (requiredType && device && device.type !== requiredType) {
              throw new Error(`"${device.name ?? mac}" is a ${DEVICE_TYPE_LABELS[device.type] ?? device.type}, not a ${DEVICE_TYPE_LABELS[requiredType] ?? requiredType} \u2014 this command doesn't apply to it`);
            }
            if (command === "set-outlet" && device) {
              const cachedOutlets = device.outlet_table;
              if (!cachedOutlets || cachedOutlets.length === 0) {
                throw new Error(`"${device.name ?? mac}" doesn't report any controllable outlets \u2014 Set Outlet Power only works on UniFi SmartPower devices (UPS, UPS Pro, PDU Pro, Smart Plug, Smart Strip, etc)`);
              }
            }
          }
          const sendRequest = async (path, method, payload) => {
            try {
              return await unifi.customApiRequest(path, method, payload);
            } catch (firstError) {
              if (path.includes("/api/s/") && !path.includes("/proxy/network")) {
                return await unifi.customApiRequest(path.replace("/api/s/", "/proxy/network/api/s/"), method, payload);
              }
              throw firstError;
            }
          };
          let result;
          if (command === "set-outlet") {
            const [freshDevice] = await unifi.listDevices(mac);
            const deviceWithOutlets = freshDevice;
            if (!deviceWithOutlets) {
              throw new Error(`No device found with MAC ${mac}`);
            }
            if (!deviceWithOutlets.outlet_table || deviceWithOutlets.outlet_table.length === 0) {
              throw new Error(`"${deviceWithOutlets.name ?? mac}" doesn't report any controllable outlets \u2014 Set Outlet Power only works on UniFi SmartPower devices (UPS, UPS Pro, PDU Pro, Smart Plug, Smart Strip, etc)`);
            }
            const outletIdx = event.options.outlet_idx;
            const outletOn = event.options.outlet_on;
            const currentOutlets = deviceWithOutlets.outlet_table ?? [];
            const overrides = currentOutlets.map((o) => ({
              index: o.index,
              relay_state: o.index === outletIdx ? outletOn : o.relay_state ?? true
            }));
            if (!overrides.some((o) => o.index === outletIdx)) {
              overrides.push({ index: outletIdx, relay_state: outletOn });
            }
            const path = `/api/s/${self2.config.site}/rest/device/${deviceWithOutlets._id}`;
            result = await sendRequest(path, "PUT", { outlet_overrides: overrides });
          } else {
            const spec = COMMAND_SPEC[command];
            const payload = { cmd: command };
            payload[spec.macField] = spec.macField === "macs" ? [mac] : mac;
            if (command === "authorize-guest")
              payload.minutes = event.options.minutes;
            if (command === "restart")
              payload.reboot_type = event.options.reboot_type;
            if (command === "power-cycle")
              payload.port_idx = event.options.port_idx;
            const path = `/api/s/${self2.config.site}/${spec.endpoint}`;
            result = await sendRequest(path, "POST", payload);
          }
          self2.log("debug", `Utility: Send Device Command: ${JSON.stringify(result)}`);
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          self2.log("error", `Utility: Send Device Command failed: ${message}`);
        }
      }
    }
  };
}

