function deviceChoices(self2, idField, filterType) {
  return self2.devices.filter((d) => !filterType || d.type === filterType).map((d) => ({
    id: d[idField],
    label: `${d.name ?? d.model} (${DEVICE_TYPE_LABELS[d.type] ?? d.type}) \u2014 ${d.mac}`
  }));
}
function clientChoices(self2) {
  return self2.clients.map((c) => ({
    id: c.mac,
    label: `${c.name ?? c.hostname ?? c.mac} \u2014 ${c.mac}`
  }));
}
